 private void mark(String message){System.out.println("ECONOMY_NATIVE_PROBE "+message);try{Files.writeString(game().resolve("probe-progress.txt"),message);}catch(Exception ignored){}}
 public void onInitializeClient(){
  ScreenEvents.AFTER_INIT.register((client,screen,width,height)->{if(screen.getClass().getName().startsWith("dev.dsmp.economy.ui."))ScreenEvents.afterExtract(screen).register((s,g,mx,my,delta)->{frames++;g.text(client.font,"NATIVE 26.3 TEST - SAMPLE DATA",8,(s instanceof WindowedScreen ws?ws.menuWindow().viewportHeight():s.height)-10,0xFFFFFFFF);});});
  ClientLifecycleEvents.CLIENT_STARTED.register(client->{mod=new EconomyTrackerClient();DesignManager.initialize(mod);TrackingControls.initialize();try{TrackingControls.save(new TrackingOptions());}catch(Exception ex){throw new RuntimeException(ex);}DesignAccess.install(new AccessOptions());try{new AccessStore(game().resolve("config/economy-tracker/accessibility.json")).save(new AccessOptions());}catch(Exception ex){throw new RuntimeException(ex);}mod.ledger.recordBalance(Money.parse("123M"),System.currentTimeMillis());mod.ledger.recordBet(new Ledger.Bet("sample-a","ProbeWinner",Money.parse("1M"),System.currentTimeMillis()));mod.ledger.recordBet(new Ledger.Bet("sample-b","ProbeLoser",-Money.parse("2M"),System.currentTimeMillis()));deadline=System.currentTimeMillis()+210000;client.gui.setScreen(new DashboardScreen(mod));dashboard=client.gui.screen();mark("STARTED");});
  ClientTickEvents.END_CLIENT_TICK.register(client->{if(mod==null)return;if(++ticks%15!=0)return;client.gui.toastManager().clear();try{if(System.currentTimeMillis()>deadline)throw new AssertionError("Native smoke timeout at step "+step);run(client);}catch(Throwable ex){ex.printStackTrace();mark("FAIL "+ex);try{Files.writeString(game().resolve("probe-result.txt"),"FAIL "+ex);}catch(Exception ignored){}mod=null;client.stop();}});
 }
